entries[124513] = { ["name"] = "Reaper's Harvest", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Death Knight\nEquip: Marrowrend deals 0 % increased damage, and heals you for 0 % of damage dealt.\nEquip: Obliterate deals 0 % additional damage as Frost damage.\nEquip: Your disease ticks have a 0 % chance to trigger Wandering Plague, dealing the same damage again to the target and all other enemies within 8 yards, split evenly.\nSell Price:" }
entries[124514] = { ["name"] = "Seed of Creation", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Druid\nEquip: Starsurge has a 1 % chance to also trigger Starfall.\nEquip: Increases the duration of Tiger's Fury and Berserk by 2 %.\nEquip: All damage received is reduced by (Attack Power * 0 / 100) (increased by Attack Power). All damage prevented this way is dealt back to the attacker as Nature damage. This effect cannot absorb more than 90% of an attack.\nEquip: Your Rejuvenation and Lifebloom ticks have a 0 % chance to also heal other allies within 15 yds.\nSell Price:" }
entries[124515] = { ["name"] = "Talisman of the Master Tracker", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Hunter\nEquip: Increases the duration of Bestial Wrath by 1 %.\nEquip: Your shots deal ( 0 / 100)% increased damage per yard between you and the target.\nEquip: Increases the damage done by your Mongoose Bite by 0 %.\nSell Price:" }
entries[124516] = { ["name"] = "Tome of Shifting Words", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Mage\nEquip: Arcane Power also increases the damage and reduces the cast time and global cooldown of Arcane Blast by 0 %.\nEquip: Fire Blast has a 1 % chance to also cast a Flamestrike at the target's location.\nEquip: Ice Lances cast immediately following a Frostbolt deal 1 % more damage.\nSell Price:" }
entries[124517] = { ["name"] = "Sacred Draenic Incense", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Monk\nEquip: When you drop below 1 % health, you gain a charge of Ironskin Brew. Ironskin Brew also increases damage dealt by 0 %.\nEquip: Soothing Mist also heals allies around the target for 0 % of the primary target.\nEquip: You have a 0 % chance to perform a free Rising Sun Kick after each Fists of Fury, Blackout Kick, or normal Rising Sun Kick.\nSell Price:" }
entries[124518] = { ["name"] = "Libram of Vindication", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Paladin\nEquip: Healing with Holy Shock grants you Magnifying Light, increasing the healing of your next Holy Light or Flash of Light within 6 sec by 1 %.\nEquip: When you drop below 1 % health, the Light will heal you for (Attack Power * 11 / 100), and deal (Attack Power * 11 / 100) Holy damage to nearby enemies. This cannot occur again for 12 sec.\nEquip: Crusader Strike increases your damage by ( 4 / 100)% for 10 sec, stacking up to 3 times. This effect is reset if you Crusader Strike a different target.\nSell Price:" }
entries[124519] = { ["name"] = "Repudiation of War", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Priest\nEquip: Your Shadow Mend, Plea, Power Word: Radiance, and Penance also grant Naaru's Discipline to allies, reducing damage taken by 0 % for 10 sec.\nEquip: Increases the healing done by your Heal and Flash Heal by 0 %.\nEquip: Mind Flay damage applies Mental Fatigue to the target, increasing damage taken from Mind spells by ( 8 / 100)% for 10 sec, stacking up to 5 times.\nSell Price:" }
entries[124520] = { ["name"] = "Bleeding Hollow Toxin Vessel", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Rogue\nEquip: Envenom also increases the critical strike chance of Mutilate by 0 %.\nEquip: Your Run Through now deals 1 % additional damage.\nEquip: Increases the damage of Shadowstrike by 1 %.\nSell Price:" }
entries[124521] = { ["name"] = "Core of the Primal Elements", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Shaman\nEquip: Increases the damage and duration of Flame Shock by 1 %.\nEquip: Your Windfury Attacks deal 4 % increased damage and generate 2 additional Maelstrom.\nEquip: Casting Healing Surge, Chain Heal, or Healing Wave on a target with your Riptide on it has a 1 % chance to spread that Riptide to another nearby ally.\nSell Price:" }
entries[124522] = { ["name"] = "Fragment of the Dark Star", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Warlock\nEquip: Reduces the duration and period of Agony, Unstable Affliction, and Corruption by 0 %.\nEquip: Hand of Gul'dan has a 1 % chance to also summon 3 Wild Imps.\nEquip: Incinerate increases the critical strike chance of your spells against that target by 0 % for 10 sec, stacking up to 5 times.\nSell Price:" }
entries[124523] = { ["name"] = "Worldbreaker's Resolve", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nClasses: Warrior\nEquip: Your auto attacks have a 0 % chance to reset the cooldown of Colossus Smash.\nEquip: Your auto attacks increase your haste by ( 2 / 100)% for 6 sec, stacking up to 10 times. This effect is reset if you auto attack a different target.\nEquip: Protection, Protection\nShield Block now also reduces magic damage taken by 0 %. Ignore Pain now also increases your Armor by 0 %. Shield Charge now increases Shield Slam, Revenge, and Heroic Strike damage by an additional 0 %.\nSell Price:" }
