entries[124634] = { ["name"] = "Thorasus, the Stone Heart of Draenor", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Strength\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\nUse: Awakens the powers of all the Savage Hallows worn by you and your allies, increasing damage dealt by [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% for 15 sec.\n\nWhen this effect ends, each empowered player unleashes a blast of light that strikes all enemies within 20 yards of the initiating player's location, inflicting damage equal to ( 27 / 100)% of all damage they dealt while empowered. (2 min shared cooldown)\n\"One of the three Savage Hallows created by Archmage Khadgar.\"\nSell Price:" }
entries[124635] = { ["name"] = "Nithramus, the All-Seer", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Intellect\n+4 Stamina\n+ 2 Versatility\n+ 3 Mastery\nUse: Awakens the powers of all the Savage Hallows worn by you and your allies, increasing damage dealt by [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% for 15 sec.\n\nWhen this effect ends, each empowered player unleashes a blast of light that strikes all enemies within 20 yards of the initiating player's location, inflicting damage equal to ( 27 / 100)% of all damage they dealt while empowered. (2 min shared cooldown)\n\"One of the three Savage Hallows created by Archmage Khadgar.\"\nSell Price:" }
entries[124636] = { ["name"] = "Maalus, the Blood Drinker", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Agility\n+4 Stamina\n+ 3 Critical Strike\n+ 3 Versatility\nUse: Awakens the powers of all the Savage Hallows worn by you and your allies, increasing damage dealt by [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% for 15 sec.\n\nWhen this effect ends, each empowered player unleashes a blast of light that strikes all enemies within 20 yards of the initiating player's location, inflicting damage equal to ( 27 / 100)% of all damage they dealt while empowered. (2 min shared cooldown)\n\"One of the three Savage Hallows created by Archmage Khadgar.\"\nSell Price:" }
entries[124637] = { ["name"] = "Sanctus, Sigil of the Unbroken", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 [Agility or Strength]\n+4 Stamina\n+ 2 Versatility\n+ 3 Mastery\nUse: Awakens the powers of Sanctus rings worn by you and your allies, granting [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 54 / 100]% Versatility for 15 sec.\n\nFor the duration of this effect, all damage and healing received is divided evenly among empowered allies. (2 min shared cooldown)\nSell Price:" }
entries[124638] = { ["name"] = "Etheralus, the Eternal Reward", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+3 Intellect\n+4 Stamina\n+ 2 Haste\n+ 3 Versatility\nUse: Awakens the powers of Etheralus rings worn by you and your allies, increasing healing and absorption done by [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% for 15 sec.\n\nWhen this effect ends, each empowered player unleashes a burst of energy that shields your allies, absorbing damage equal to ( 27 / 100)% of all healing done while empowered, divided evenly among the shielded players. (2 min shared cooldown)\nSell Price:" }
